import React, { useState, useEffect } from 'react';
import './AppMain.css'
import { User, Download, Calendar, ClipboardPenLine, Plus } from 'lucide-react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios'

function AppMain() {
  const location = useLocation();
  const navigate = useNavigate();
  const username = location.state?.username || "Invitado";
  const [showMenu, setShowMenu] = useState(false);
  const [historial, setHistorial] = useState([]);
  const [active, setActive] = useState("registro");

  // Nuevo Registro
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState ({
    username: username,
    proyect: '',
    task: '',
    hours: '',
    description: ''
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/history/create/history', formData, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      alert(res.data);
      setShowForm(false);
      window.location.reload();
    }).catch(err => {
      console.error("Error al guardar el historial", err);
    })
  }

  // Cargar los datos al cargar la página
  useEffect(() => {
    axios.get('http://localhost:8081/api/history', {
      auth: {
        username: 'ventu',
        password: '123'
      }
    })
      .then(res => {
        setHistorial(res.data);
      })
      .catch(err => {
        console.error("Error al obtener historial:", err);
      });
  }, []);

  const toggleMenu = () => {
    setShowMenu(!showMenu);
  };

  const logout = () => {
    navigate("/");
  };

  return (
    <div className='Main'>
      <header className='Main-header'>
        <img src="/logoQuiros.png" />
        <div className='usuario' onClick={toggleMenu}>
          <User />
          <strong>{username}</strong>
        </div>
        {showMenu && (
          <div className='dropdown'>
            <button onClick={logout}>Cerrar Sesion</button>
          </div>
        )}
      </header>
      <main>
        <div className='Main-menu'>
          <button className={active === "registro" ? "active" : ""} onClick={() => setActive("registro")}><Calendar />Registro Horas</button>
          <button className={active === "reportes" ? "active" : ""} onClick={() => setActive("reportes")}><ClipboardPenLine />Reportes</button>
        </div>
        <div className='Main-body'>
          <button><Download /></button>
          <button onClick={() => setShowForm(true)}><Plus />Añadir registro</button>
          <table className='table'>
            <thead>
              <tr>
                <td>Usuario</td>
                <td>Proyecto</td>
                <td>Tarea</td>
                <td>Horas</td>
                <td>Descripcion</td>
              </tr>
            </thead>
            <tbody>
              {historial.map((item, index) => (
                <tr key={index}>
                  <td>{item.user}</td>
                  <td>{item.proyect}</td>
                  <td>{item.task}</td>
                  <td>{item.hours}</td>
                  <td>{item.description}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </main>
    </div>
  );
}

export default AppMain;
